      return { items, vodafoneCashNumber: setting[0]?.value ?? "", subscriptionRequired: settingMap.get("owner_subscription_required") !== "off", freeTrialEnabled: settingMap.get("owner_free_trial_enabled") === "on", freeTrialDays };
